  ('mat5', 'Final de práctica 08', 'Simulacro de examen final con contenidos de las unidades 1 a 9: 20 preguntas de 5 afirmaciones V/F. Rendilo con tiempo (120 min) o practicá sin límite.', 120, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": true, "fpPenalty": 0.2, "fnPenaltyEnabled": true, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "ma-final-08-q01", "type": "true_false_statements", "topic": "Unidad 1 · Estructuras discretas y lógica", "prompt": "Clasificar cada fórmula proposicional (tautología, contradicción o contingencia):", "statements": [{"text": "$\\big(p \\land (p \\to q)\\big) \\to q$ es una tautología.", "answer": true}, {"text": "$(p \\land q) \\to r$ es una tautología.", "answer": false}, {"text": "$p \\land \\lnot p$ es una contradicción.", "answer": true}, {"text": "$\\big((p \\lor q) \\land \\lnot p\\big) \\to q$ es una contingencia.", "answer": false}, {"text": "$p \\lor \\lnot p$ es una contradicción.", "answer": false}]}, {"id": "ma-final-08-q02", "type": "true_false_statements", "topic": "Unidad 1 · Estructuras discretas y lógica", "prompt": "Equivalencias lógicas. Indicar V o F:", "statements": [{"text": "$\\lnot (p \\to q)$ es lógicamente equivalente a $\\lnot p \\to \\lnot q$.", "answer": false}, {"text": "$p \\to q$ es lógicamente equivalente a $\\lnot q \\to \\lnot p$.", "answer": true}, {"text": "$p \\to q$ es lógicamente equivalente a $q \\to p$.", "answer": false}, {"text": "$\\lnot (p \\lor q)$ es lógicamente equivalente a $\\lnot p \\lor \\lnot q$.", "answer": false}, {"text": "$p \\to q$ es lógicamente equivalente a $\\lnot p \\to \\lnot q$.", "answer": false}]}, {"id": "ma-final-08-q03", "type": "true_false_statements", "topic": "Unidad 1 · Estructuras discretas y lógica", "prompt": "Técnicas de conteo. Indicar V o F:", "statements": [{"text": "Se pueden formar $15$ comités distintos de $4$ personas con un grupo de $6$.", "answer": true}, {"text": "Con un alfabeto de $36$ símbolos hay $42840$ claves p